import assert from 'node:assert/strict';import {randomUUID} from 'node:crypto';
import {lanes as thirteen} from './maintenance-thirteen-lanes.mjs';
import {identity} from './model-settings.mjs';
export const lanes={...thirteen,selectedArchive:{key:'selected_archive',begin:()=>({action:'prepare-export',...identity,path:'/home/root/backups/history-new',invocation:randomUUID()})}};
const isRead=name=>['inspectSourceCache','inspectConversations'].includes(name);
export async function verifyHundredEightyTwoDirections(request){let pairs=0,old156=0;for(const [old,a]of Object.entries(lanes))for(const [newer,b]of Object.entries(lanes)){if(old===newer)continue;const ready=(await request(old,a.begin()))[a.key];assert.ok(isRead(old)?ready.status==='reported':ready.reference,old);const next=(await request(newer,b.begin()))[b.key];assert.ok(isRead(newer)?next.status==='reported':next.reference,newer);if(!isRead(old)){const q=a.change?{action:'save',...identity,reference:ready.reference,change:a.change}:a.changes?{action:'save',...identity,reference:ready.reference,changes:a.changes}:old==='memoryForget'?{action:'confirm',reference:ready.reference}:old==='conversationManagement'?{action:'prepare',...identity,reference:ready.reference,invocation:randomUUID()}:old==='selectedArchive'?{action:'confirm-export',...identity,reference:ready.reference,invocation:randomUUID()}:old==='ordinaryRestore'?{action:'confirm',...identity,reference:ready.reference,invocation:randomUUID()}:old==='sourceCacheCleanup'?{action:'confirm',...identity,reference:ready.reference,invocation:randomUUID()}:{action:'confirm',...identity,reference:ready.reference};const v=(await request(old,q))[a.key];assert.ok(['invalidated','unavailable','not-dispatched'].includes(v.state),`${old} after ${newer}: ${v.state}`);}if(old!=='selectedArchive'&&newer!=='selectedArchive')old156++;pairs++;}assert.equal(pairs,182);assert.equal(old156,156);}
export async function verifyHundredEightyTwoBusyDirections(request,control){let pairs=0;for(const [old,a]of Object.entries(lanes)){await control.hold();const q=a.begin();if(old==='selectedArchive')q.action='inspect';const pending=request(old,q);await control.entered();try{const before=await control.snapshot();for(const [newer,b]of Object.entries(lanes)){if(old===newer)continue;const v=(await request(newer,b.begin()))[b.key];assert.equal(isRead(newer)?v.status:v.state,'busy',`${old} holds, ${newer} refused`);assert.deepEqual(await control.snapshot(),before,'Busy has no hook/cancel/raw side effect');pairs++;}}finally{await control.release();}await pending;}assert.equal(pairs,182);}
